scaling-tasks.code:
let total = await withTaskGroup(of: int.self) { group in
    for id in 1...8 {
        group.addTask { await work(id) }
    }
    var sum = 0
    for await value in group { sum += value }
    return sum
}

scaling-tasks.prelude:
func work(_ id: int) async -> int { id * 10 }
func main() async -> int32 {
//BODY
    print(total)
    return 0
}

